import os
import re
from typing import Any, Dict, List, Optional

import requests


class ContentSafetyError(Exception):
    pass


class TisaneContentSafety:
    def __init__(
        self,
        api_key: Optional[str] = None,
        language: str = "en",
        base_url: str = "https://api.tisane.ai",
        timeout: int = 30,
    ) -> None:
        self.api_key = api_key or os.getenv("TISANE_API_KEY")
        if not self.api_key:
            raise ValueError("Missing TISANE_API_KEY")
        self.language = language
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout

    def analyze_text(self, text: str) -> Dict[str, Any]:
        url = f"{self.base_url}/parse"
        headers = {
            "Ocp-Apim-Subscription-Key": self.api_key,
            "Content-Type": "application/json",
        }
        payload = {
            "language": self.language,
            "content": text,
            "settings": {
                "snippets": True,
                "explain": True,
            },
        }

        response = requests.post(url, headers=headers, json=payload, timeout=self.timeout)
        if not response.ok:
            raise ContentSafetyError(f"Tisane API error {response.status_code}: {response.text}")
        return response.json()

    def flag_unsafe_spans(self, text: str) -> Dict[str, Any]:
        result = self.analyze_text(text)
        spans = self._extract_spans(result, text)
        flagged = len(spans) > 0
        return {
            "provider": "Tisane",
            "flagged": flagged,
            "spans": spans,
            "raw": result,
        }

    def redact_unsafe_spans(self, text: str, replacement: str = "[REDACTED]") -> Dict[str, Any]:
        flagged = self.flag_unsafe_spans(text)
        spans = flagged["spans"]
        redacted_text = self._apply_redactions(text, spans, replacement)
        return {
            "provider": "Tisane",
            "flagged": flagged["flagged"],
            "spans": spans,
            "redacted_text": redacted_text,
            "raw": flagged["raw"],
        }

    def _extract_spans(self, data: Dict[str, Any], original_text: str) -> List[Dict[str, Any]]:
        spans: List[Dict[str, Any]] = []

        abuse = data.get("abuse", [])
        for item in abuse:
            snippet = item.get("text") or item.get("snippet")
            labels = item.get("tags") or item.get("type") or []
            explanation = item.get("explanation")
            severity = item.get("severity")
            spans.extend(
                self._snippet_to_spans(
                    original_text=original_text,
                    snippet=snippet,
                    category="abuse",
                    labels=labels,
                    severity=severity,
                    explanation=explanation,
                )
            )

        entities = data.get("entities", [])
        for item in entities:
            if not self._is_unsafe_entity(item):
                continue
            snippet = item.get("text")
            labels = item.get("type") or item.get("subtype") or []
            explanation = item.get("comment")
            severity = item.get("severity")
            spans.extend(
                self._snippet_to_spans(
                    original_text=original_text,
                    snippet=snippet,
                    category="entity",
                    labels=labels,
                    severity=severity,
                    explanation=explanation,
                )
            )

        sentences = data.get("sentiment_expressions", [])
        for item in sentences:
            if not self._is_unsafe_sentiment(item):
                continue
            snippet = item.get("text")
            labels = item.get("reasons") or item.get("markers") or []
            explanation = item.get("explanation")
            severity = item.get("polarity")
            spans.extend(
                self._snippet_to_spans(
                    original_text=original_text,
                    snippet=snippet,
                    category="sentiment_expression",
                    labels=labels,
                    severity=severity,
                    explanation=explanation,
                )
            )

        return self._merge_spans(spans)

    def _is_unsafe_entity(self, item: Dict[str, Any]) -> bool:
        text = " ".join(
            str(x)
            for x in [
                item.get("type"),
                item.get("subtype"),
                item.get("class"),
                item.get("comment"),
            ]
            if x is not None
        ).lower()
        keywords = {
            "criminal_activity",
            "weapon",
            "drugs",
            "controlled_substance",
            "hate",
            "sexual",
            "violence",
            "self-harm",
            "extremism",
            "personal_attack",
        }
        return any(k in text for k in keywords)

    def _is_unsafe_sentiment(self, item: Dict[str, Any]) -> bool:
        blob = " ".join(
            str(x)
            for x in [
                item.get("text"),
                item.get("explanation"),
                item.get("reasons"),
                item.get("markers"),
            ]
            if x is not None
        ).lower()
        keywords = {
            "insult",
            "threat",
            "abuse",
            "hate",
            "harassment",
            "violence",
            "sexual",
            "self-harm",
        }
        return any(k in blob for k in keywords)

    def _snippet_to_spans(
        self,
        original_text: str,
        snippet: Optional[str],
        category: str,
        labels: Any,
        severity: Any,
        explanation: Optional[str],
    ) -> List[Dict[str, Any]]:
        if not snippet or not isinstance(snippet, str):
            return []

        matches = list(re.finditer(re.escape(snippet), original_text, flags=re.IGNORECASE))
        if not matches:
            return []

        if isinstance(labels, str):
            norm_labels = [labels]
        elif isinstance(labels, list):
            norm_labels = [str(x) for x in labels]
        else:
            norm_labels = [str(labels)] if labels is not None else []

        return [
            {
                "start": m.start(),
                "end": m.end(),
                "text": original_text[m.start():m.end()],
                "category": category,
                "labels": norm_labels,
                "severity": severity,
                "explanation": explanation,
            }
            for m in matches
        ]

    def _merge_spans(self, spans: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        if not spans:
            return []

        spans = sorted(spans, key=lambda s: (s["start"], s["end"]))
        merged: List[Dict[str, Any]] = [spans[0].copy()]

        for span in spans[1:]:
            last = merged[-1]
            if span["start"] <= last["end"]:
                last["end"] = max(last["end"], span["end"])
                last["text"] = last["text"] if len(last["text"]) >= len(span["text"]) else span["text"]
                last["labels"] = sorted(set(last.get("labels", []) + span.get("labels", [])))
                if span.get("explanation"):
                    existing = last.get("explanation")
                    if existing and span["explanation"] not in existing:
                        last["explanation"] = f"{existing}; {span['explanation']}"
                    elif not existing:
                        last["explanation"] = span["explanation"]
            else:
                merged.append(span.copy())

        return merged

    def _apply_redactions(self, text: str, spans: List[Dict[str, Any]], replacement: str) -> str:
        if not spans:
            return text

        parts: List[str] = []
        cursor = 0
        for span in sorted(spans, key=lambda s: s["start"]):
            start = max(cursor, span["start"])
            end = span["end"]
            if start > cursor:
                parts.append(text[cursor:start])
            if end > start:
                parts.append(replacement)
                cursor = end
        if cursor < len(text):
            parts.append(text[cursor:])
        return "".join(parts)
